from pathlib import Path
import ee,pandas as pd,numpy as np
out=Path(__file__).resolve().parents[1]/'experiments/E01_spatial_support';ee.Initialize(project=__import__('os').environ.get('EE_PROJECT','ee-abao9474'));ee.data.setDeadline(55000);g=pd.read_csv(out/'pilot_selected_grids.csv');fc=ee.FeatureCollection([ee.Feature(ee.Geometry.Point([r.lon,r.lat]),{'grid_id':r.grid_id}) for r in g.itertuples()]);gsw=ee.Image('JRC/GSW1_4/GlobalSurfaceWater');p=gsw.select('occurrence').unmask(0).gte(80).And(gsw.select('seasonality').unmask(0).gte(10));dist=p.unmask(0).fastDistanceTransform(1024).sqrt().multiply(30).rename('original_algorithm_distance_m').unmask(30720).min(30720).toFloat();r=dist.sampleRegions(collection=fc,properties=['grid_id'],scale=300,geometries=False,tileScale=4).getInfo();m=pd.DataFrame([x['properties'] for x in r['features']]).merge(g,on='grid_id');m['original_algorithm_distance_km']=m.original_algorithm_distance_m/1000;m['difference_km']=m.original_algorithm_distance_km-m.dist_perm_water_km;m.to_csv(out/'original_GEE_algorithm_exact_rerun.csv',index=False);print(m[['grid_id','original_algorithm_distance_km','dist_perm_water_km','difference_km']].to_string(index=False));print('max_abs_error',m.difference_km.abs().max())
